#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-or-later WITH AdditionRef-Terpoir-AppStore-exception
# Copyright (C) 2026 The Terpoir Authors
# See LICENSING.md for the additional permission under GPLv3 section 7.
#
# Builds the Rust core for iOS (docs/roadmap.md, "iOS", I1) on a Mac:
# terpoir-ffi as a static library for iPhones (aarch64-apple-ios) and the
# simulator on Apple silicon (aarch64-apple-ios-sim), with SQLCipher and
# OpenSSL from source as on Android, packed into
# ios/TerpoirCore/TerpoirCoreFFI.xcframework, and the Swift bindings,
# generated by the workspace's own uniffi-bindgen, into the TerpoirCore
# package. Both outputs are build products, never committed.
#
# Usage: ios/scripts/build-core.sh   (macOS with Xcode; rustup)

set -euo pipefail

die() { echo "build-core.sh: $*" >&2; exit 1; }
[ "$(uname -s)" = Darwin ] || die "needs macOS with Xcode"
command -v xcodebuild >/dev/null || die "xcodebuild missing"

root=$(cd "$(dirname "$0")/../.." && pwd)
core="$root/core"
package="$root/ios/TerpoirCore"
work="$root/ios/build"
targets=(aarch64-apple-ios aarch64-apple-ios-sim)

# Matches the package's platforms (Package.swift): C code (SQLCipher,
# OpenSSL) and Rust both target it.
export IPHONEOS_DEPLOYMENT_TARGET=17.0

cd "$core"
rustup target add "${targets[@]}" >/dev/null
for target in "${targets[@]}"; do
    cargo build --locked --release -p terpoir-ffi --target "$target"
done

# The bindings come from a host build of the same library: uniffi reads the
# exported interface from it, and the interface is the same on every target.
cargo build --locked -p terpoir-ffi -p uniffi-bindgen
rm -rf "$work"
mkdir -p "$work/bindings" "$work/headers"
cargo run --locked -q -p uniffi-bindgen -- generate \
    --library target/debug/libterpoir_ffi.dylib --language swift --out-dir "$work/bindings"
cp "$work/bindings/TerpoirCoreFFI.h" "$work/headers/"
cp "$work/bindings/TerpoirCoreFFI.modulemap" "$work/headers/module.modulemap"

rm -rf "$package/TerpoirCoreFFI.xcframework"
args=()
for target in "${targets[@]}"; do
    args+=(-library "$core/target/$target/release/libterpoir_ffi.a" -headers "$work/headers")
done
xcodebuild -create-xcframework "${args[@]}" -output "$package/TerpoirCoreFFI.xcframework"
cp "$work/bindings/TerpoirCore.swift" "$package/Sources/TerpoirCore/TerpoirCore.swift"
# The compatibility fixtures, for the tests (CompatFixtureTests): the
# release databases and exports, without the generator's source.
fixtures="$package/Tests/TerpoirCoreTests/Fixtures"
rm -rf "$fixtures"
mkdir -p "$fixtures"
for dir in crates/terpoir-ffi/tests/fixtures/v*; do
    [ -d "$dir" ] && cp -R "$dir" "$fixtures/"
done
echo "Built TerpoirCoreFFI.xcframework and TerpoirCore.swift"
